/**
 * Display "1 item",  "11 items" or "4 of 10" if list is filtered via search box.
 */
function updateCountBox() {
  const countBox = document.getElementById("countBox");
  const sum = gCurrentFilterList.filterCount;
  const len = gFilterListbox.itemCount;

  if (len == sum) {
    // "N items"
    document.l10n.setAttributes(countBox, "filter-count-items", { count: sum });
    return;
  }

  // "N of M"
  document.l10n.setAttributes(countBox, "filter-count-visible-of-total", {
    visible: len,
    total: sum,
  });
}
